INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Abnahmetest bei jedem Projekt zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Vertrag"}, {"text": "Ja", "correct": false, "because": "Nicht gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was prüfe ich mit einem Abnahmetest?', 3, '[{"text": "Vertragsgemäße Funktionalität", "correct": true, "because": "Erfüllung der Anforderungen"}, {"text": "Zukünftige Wartungskosten", "correct": false, "because": "Nicht primär"}, {"text": "Entwicklungszeit", "correct": false, "because": "Irrelevant für Abnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Abnahmetest?', 5, '[{"text": "Testfälle", "correct": true, "because": "Definiert Anforderungen"}, {"text": "Ergebnisdokumentation", "correct": true, "because": "Nachweis der Erfüllung"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Testbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Abnahmetests basieren auf Anforderungen. b) Sie ersetzen Integrationstests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Integrationstests sind separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines Abnahmetests?', 4, '[{"text": "Vertragsanforderungen", "correct": false, "because": "Grundlage des Tests"}, {"text": "Testumgebung", "correct": false, "because": "Wichtig für Realismus"}, {"text": "Projektbudget", "correct": true, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Abnahmetest Mängel übersehen darf?', 2, '[{"text": "Nein", "correct": true, "because": "Soll alle relevanten Fehler finden"}, {"text": "Ja", "correct": false, "because": "Ziel ist Mängelfreiheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer führt einen Abnahmetest typischerweise durch?', 3, '[{"text": "Auftraggeber", "correct": true, "because": "Prüft Vertragsleistung"}, {"text": "Entwicklerteam", "correct": false, "because": "Eher interne Tests"}, {"text": "Externe Auditoren", "correct": false, "because": "Nur in Spezialfällen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Durchführung eines Abnahmetests?', 5, '[{"text": "Prüfung der Spezifikationen", "correct": true, "because": "Vergleich mit Anforderungen"}, {"text": "Protokollierung", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "Code-Analyse", "correct": false, "because": "Nicht Teil der Abnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Abnahmetests sind Endprüfungen. b) Sie testen nur Software. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Hardware oder Dienstleistungen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Abnahmetest unwichtig?', 4, '[{"text": "Testkriterien", "correct": false, "because": "Definiert Erfolg"}, {"text": "Dokumentation", "correct": false, "because": "Nachweis nötig"}, {"text": "Entwickleranzahl", "correct": true, "because": "Kein Testfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Abnahmetest automatisiert sein?', 2, '[{"text": "Ja", "correct": true, "because": "Teilweise automatisierbar"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein Abnahmetest?', 4, '[{"text": "Sicherung der Qualität", "correct": true, "because": "Bestätigt Anforderungen"}, {"text": "Risikominimierung", "correct": true, "because": "Findet Mängel"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Abnahmetests immer fehlerfrei sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Geringfügige Mängel können toleriert werden"}, {"text": "Ja", "correct": false, "because": "Abhängig von Vertrag"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Abnahmetest?', 3, '[{"text": "Vertragsanforderungen", "correct": true, "because": "Kern der Prüfung"}, {"text": "Testgeschwindigkeit", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Teamgröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Abnahmetests prüfen Funktionalität. b) Sie ersetzen Unit-Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unit-Tests sind separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlecht geplanter Abnahmetest?', 5, '[{"text": "Unklare Ergebnisse", "correct": true, "because": "Fehlende Kriterien"}, {"text": "Verzögerte Abnahme", "correct": true, "because": "Mängel unentdeckt"}, {"text": "Schnellere Durchführung", "correct": false, "because": "Nicht vorteilhaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Abnahmetest unwichtig?', 3, '[{"text": "Anforderungsliste", "correct": false, "because": "Basis der Prüfung"}, {"text": "Testumgebung", "correct": false, "because": "Simuliert Betrieb"}, {"text": "Entwicklungsplattform", "correct": true, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Abnahmetest immer vom Kunden definiert?', 3, '[{"text": "Nein", "correct": true, "because": "Kann auch gemeinsam erstellt werden"}, {"text": "Ja", "correct": false, "because": "Kooperation möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Abnahmetests auch Hardware betreffen können?', 2, '[{"text": "Ja", "correct": true, "because": "Nicht auf Software beschränkt"}, {"text": "Nein", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle wähle ich für die Testdurchführung?', 4, '[{"text": "Kunde oder Beauftragter", "correct": true, "because": "Prüft Vertragsleistung"}, {"text": "Entwickler", "correct": false, "because": "Interne Tests"}, {"text": "Support-Team", "correct": false, "because": "Nachgelagerte Rolle"}]');
